var title = "Block on an incline";
return { draw: function (ctx, w, h, time) {
  ctx.fillStyle = '#fafafa'; ctx.fillRect(0, 0, w, h);
  var mid = h / 2; ctx.strokeStyle = '#d1d5db'; ctx.beginPath(); ctx.moveTo(20, mid); ctx.lineTo(w - 20, mid); ctx.stroke();
  ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 2.5; ctx.beginPath();
  for (var x = 20; x <= w - 20; x += 2) { var y = mid - Math.sin((x / w) * 4 * Math.PI - time * 2.2) * h * 0.22 * Math.exp(-((x - w / 2) * (x - w / 2)) / (w * w * 0.25)); if (x === 20) ctx.moveTo(x, y); else ctx.lineTo(x, y); } ctx.stroke(); ctx.lineWidth = 1;
  ctx.strokeStyle = '#0284c7'; ctx.setLineDash([4, 4]); ctx.beginPath();
  for (var x2 = 20; x2 <= w - 20; x2 += 2) { var y2 = mid - Math.cos((x2 / w) * 4 * Math.PI - time * 2.2) * h * 0.12; if (x2 === 20) ctx.moveTo(x2, y2); else ctx.lineTo(x2, y2); } ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle = '#1a1a1d'; ctx.font = '14px sans-serif'; ctx.fillText(title, 14, 22); ctx.font = '12px sans-serif'; ctx.fillStyle = '#6b7280'; ctx.fillText('t = ' + time.toFixed(1) + ' s', w - 80, h - 12);
} };

var title = "Simple pendulum";
return { draw: function (ctx, w, h, time) {
  ctx.fillStyle = '#fafafa'; ctx.fillRect(0, 0, w, h);
  var L = h * 0.55, g = 9.81, th0 = 0.5, om = Math.sqrt(g / 1.2);
  var th = th0 * Math.cos(om * time);
  var px = w / 2, py = h * 0.12;
  var bx = px + L * Math.sin(th), by = py + L * Math.cos(th);
  ctx.strokeStyle = '#1a1a1d'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(px - 60, py); ctx.lineTo(px + 60, py); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(bx, by); ctx.stroke();
  ctx.fillStyle = '#7c3aed'; ctx.beginPath(); ctx.arc(bx, by, 16, 0, Math.PI * 2); ctx.fill();
  ctx.setLineDash([4, 4]); ctx.strokeStyle = '#9ca3af'; ctx.beginPath(); ctx.arc(px, py, L, Math.PI / 2 - th0, Math.PI / 2 + th0); ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle = '#1a1a1d'; ctx.font = '14px sans-serif'; ctx.fillText(title, 14, 22);
  ctx.fillStyle = '#e11d48'; ctx.fillText('theta = ' + th.toFixed(2) + ' rad', 14, h - 16);
} };
